{"file_path":"src/pointer.js","content":"/** JSON Pointer parsing, formatting and resolution over JSON data. */

/** Failure raised while parsing or resolving a pointer. */
export class PointerError extends Error {
  /**
   * @param {string} message reason, including the pointer position when known
   * @param {unknown} [pointer] the pointer the failure came from
   */
  constructor(message, pointer) {
    super(message);
    this.name = 'PointerError';
    this.pointer = pointer;
  }
}

const hasOwn = (object, key) => Object.prototype.hasOwnProperty.call(object, key);

/**
 * Split a pointer into decoded reference tokens.
 *
 * @param {string} pointer JSON Pointer text
 * @returns {string[]} the decoded tokens, empty for the whole-document pointer
 */
export function parsePointer(pointer) {
  if (typeof pointer !== 'string') throw new PointerError('pointer must be a string', pointer);
  if (pointer === '') return [];
  if (pointer[0] !== '/') throw new PointerError("pointer must be empty or start with '/'", pointer);
  return pointer
    .slice(1)
    .split('/')
    .map((raw) => decodeToken(raw, pointer));
}

/**
 * Decode one escaped reference token.
 *
 * @param {string} raw the token as it appears in the pointer
 * @param {string} pointer the pointer the token came from
 * @returns {string} the decoded token
 */
function decodeToken(raw, pointer) {
  let out = '';
  for (let i = 0; i < raw.length; i += 1) {
    const character = raw[i];
    if (character !== '~') {
      out += character;
      continue;
    }
    const next = raw[i + 1];
    if (next === '0') out += '~';
    else if (next === '1') out += '/';
    else throw new PointerError(`invalid escape in pointer token: ~${next === undefined ? '' : next}`, pointer);
    i += 1;
  }
  return out;
}

/**
 * Join reference tokens into a pointer.
 *
 * @param {string[]} tokens reference tokens
 * @returns {string} the pointer text, empty for no tokens
 */
export function formatPointer(tokens) {
  if (!Array.isArray(tokens)) throw new PointerError('tokens must be an array', tokens);
  let out = '';
  for (const token of tokens) {
    if (typeof token !== 'string') throw new PointerError('reference token must be a string', tokens);
    out += `/${token.split('~').join('~0').split('/').join('~1')}`;
  }
  return out;
}

/**
 * Name the JSON type of a value for error messages.
 *
 * @param {unknown} value any value
 * @returns {string} the type name
 */
export function typeName(value) {
  if (value === null) return 'null';
  if (Array.isArray(value)) return 'array';
  return typeof value;
}

/**
 * Whether a token is a canonical array index (no leading zeros, no sign).
 *
 * @param {string} token reference token
 * @returns {boolean} true when the token names an array position
 */
export function isArrayIndex(token) {
  return token === '0' || /^[1-9][0-9]*$/.test(token);
}

/**
 * Take one step into a container, reporting failures against the walked path.
 *
 * @param {unknown} value the container to index
 * @param {string} token the reference token to apply
 * @param {string[]} walked the tokens consumed so far, including this one
 * @param {string} pointer the whole pointer, for the failure
 * @returns {unknown} the selected value
 */
export function step(value, token, walked, pointer) {
  const at = formatPointer(walked);
  if (Array.isArray(value)) {
    if (!isArrayIndex(token)) throw new PointerError(`invalid array index: ${token} at ${at}`, pointer);
    const index = Number(token);
    if (index >= value.length) throw new PointerError(`index out of range: ${token} at ${at}`, pointer);
    return value[index];
  }
  if (value !== null && typeof value === 'object') {
    if (!hasOwn(value, token)) throw new PointerError(`missing property: ${token} at ${at}`, pointer);
    return value[token];
  }
  throw new PointerError(`cannot index into ${typeName(value)} at ${at}`, pointer);
}

/**
 * Resolve a pointer against a document.
 *
 * @param {unknown} document JSON data to walk
 * @param {string} pointer JSON Pointer text
 * @returns {unknown} the value the pointer selects
 */
export function resolve(document, pointer) {
  const tokens = parsePointer(pointer);
  return resolveTokens(document, tokens, pointer);
}

/**
 * Resolve already decoded tokens against a document.
 *
 * @param {unknown} document JSON data to walk
 * @param {string[]} tokens decoded reference tokens
 * @param {string} [pointer] the pointer text, for failures
 * @returns {unknown} the value the tokens select
 */
export function resolveTokens(document, tokens, pointer = formatPointer(tokens)) {
  let current = document;
  const walked = [];
  for (const token of tokens) {
    walked.push(token);
    current = step(current, token, walked, pointer);
  }
  return current;
}
"}

