{"file_path":"src/json.js","content":"/** JSON data validation, deep copying and structural comparison. */

const hasOwn = (object, key) => Object.prototype.hasOwnProperty.call(object, key);

/**
 * Set a member without ever consulting the prototype chain.
 *
 * @param {object} target the object to write to
 * @param {string} key the member name, possibly shadowing Object.prototype
 * @param {unknown} value the value to store
 * @returns {void}
 */
export function setMember(target, key, value) {
  Object.defineProperty(target, key, { value, writable: true, enumerable: true, configurable: true });
}

/**
 * Deep-copy JSON data, rejecting anything JSON cannot represent.
 *
 * @param {unknown} value the data to copy
 * @param {string} label what to call the data in the failure message
 * @returns {unknown} an independent copy
 */
export function copyJson(value, label) {
  if (value === null) return null;
  const type = typeof value;
  if (type === 'string' || type === 'boolean') return value;
  if (type === 'number') {
    if (!Number.isFinite(value)) throw new TypeError(`${label} is not JSON data`);
    return value;
  }
  if (type !== 'object') throw new TypeError(`${label} is not JSON data`);
  if (Array.isArray(value)) return value.map((item) => copyJson(item, label));
  const copy = {};
  for (const key of Object.keys(value)) setMember(copy, key, copyJson(value[key], label));
  return copy;
}

/**
 * Compare two pieces of JSON data structurally.
 *
 * @param {unknown} left one value
 * @param {unknown} right the other value
 * @returns {boolean} true when they are the same JSON
 */
export function jsonEqual(left, right) {
  if (left === null || right === null) return left === right;
  if (Array.isArray(left) || Array.isArray(right)) {
    if (!Array.isArray(left) || !Array.isArray(right) || left.length !== right.length) return false;
    return left.every((item, index) => jsonEqual(item, right[index]));
  }
  if (typeof left === 'object' || typeof right === 'object') {
    if (typeof left !== 'object' || typeof right !== 'object') return false;
    const keys = Object.keys(left);
    if (keys.length !== Object.keys(right).length) return false;
    return keys.every((key) => hasOwn(right, key) && jsonEqual(left[key], right[key]));
  }
  return left === right;
}
